                       static_cast<AVPixelFormat>(decoded->format),
                       decoded->width, decoded->height, AV_PIX_FMT_NV12,
                       SWS_BILINEAR, nullptr, nullptr, nullptr);
    if (!sws) {
      av_frame_free(&decoded);
      av_frame_free(&nv12);
      return BadVideo;
    }

