static void frame_done(void *data, wl_callback *callback, uint32_t) {
  auto cbData = static_cast<FrameCallbackData *>(data);
  wl_callback_destroy(callback);
  cbData->monitor->onFrame(cbData->scheduledID);
  delete cbData;
}

