static void layer_surface_configure(void *data,
                                    struct zwlr_layer_surface_v1 *surface,
                                    uint32_t serial, uint32_t width,
                                    uint32_t height) {
  auto monitor = static_cast<Monitor *>(data);
  monitor->m_height = height;
