639	void Monitor::onFrame(u32 scheduledID) {
640	  if (scheduledID != m_wallpaperID)
641	    return;
642	  auto now = std::chrono::steady_clock::now();
643	  auto diff = std::chrono::duration_cast<std::chrono::milliseconds>(
644	                  now - m_nextVideoFrame)
645	                  .count();
646	  // incase the compositor sends us to sleep
647	  if (diff > 100) {
648	    m_nextVideoFrame = now;
649	  }
650	  if (now >= m_nextVideoFrame && m_wallpaper != nullptr) {
651	    m_nextVideoFrame += m_wallpaper->m_frameDuration;
652	    render();
653	  }
654	  // don't render again if we have a single image unless we are in a transition
655	  if ((m_wallpaper->m_isSingleFrame && m_transitionState == nullptr) ||
656	      m_wallpaperPlaying == false)
657	    return;
658	  nextFrame();
659	}
