27	WallpaperBindError Wallpaper::bind(std::string_view path, VADisplay va_display,
28	                                   HardwareAccelerationBackend backend) {
29	  if (backend == Vaapi) {
30	    HWDEC_PIXEL_FORMAT = AV_PIX_FMT_VAAPI;
31	  } else if (backend == CudaCopy) {
32	    HWDEC_PIXEL_FORMAT = AV_PIX_FMT_CUDA;
33	  } else {
34	  }
35	
36	  if (avformat_open_input(&m_formatContext, path.data(), nullptr, nullptr) < 0)
37	    return BadVideo;
38	
39	  if (avformat_find_stream_info(m_formatContext, nullptr) < 0)
40	    return BadVideo;
41	
42	  m_videoStream = av_find_best_stream(m_formatContext, AVMEDIA_TYPE_VIDEO, -1,
43	                                      -1, &m_codec, 0);
44	
45	  // It's possible the video codec can't be hardware decoded by the driver,
46	  // that's probably unlikely for most videos so i'm gonna ignore that for now.
47	  // But images should be software decoded. Rough check
48	  auto ext = std::filesystem::path(path).extension();
49	  if (ext == ".gif" || ext == ".GIF") {
50	    return BadVideo;
51	  }
52	  if (m_videoStream < 0)
53	    return BadVideo;
54	
55	  m_codecContext = avcodec_alloc_context3(m_codec);
56	  if (!m_codecContext)
57	    return BadVideo;
58	
59	  if (avcodec_parameters_to_context(
60	          m_codecContext, m_formatContext->streams[m_videoStream]->codecpar) <
61	      0)
62	    return BadVideo;
63	  double fps = av_q2d(m_formatContext->streams[m_videoStream]->avg_frame_rate);
64	  if (fps <= 0.0)
65	    fps = 30.0;
66	
67	  m_frameDuration =
68	      std::chrono::milliseconds(static_cast<int64_t>(1000.0 / fps));
69	  int64_t frameCount = m_formatContext->streams[m_videoStream]->nb_frames;
70	
71	  // check if is static image that won't be decoded on GPU
72	  if ((frameCount == 1 || frameCount == 0) &&
73	      (ext != ".mp4" && ext != ".mkv")) {
74	    m_isSingleFrame = true;
75	    return decodeSingleFrameNV12();
76	  }
77	
78	  // Allocate hardware device context
79	  if (backend == Vaapi) {
80	    m_hwDeviceContext = av_hwdevice_ctx_alloc(AV_HWDEVICE_TYPE_VAAPI);
81	    if (!m_hwDeviceContext)
82	      return NoHarwareDecoding;
83	
84	    auto *hwctx =
85	        reinterpret_cast<AVHWDeviceContext *>(m_hwDeviceContext->data);
86	    auto *vaapi = reinterpret_cast<AVVAAPIDeviceContext *>(hwctx->hwctx);
87	
88	    vaapi->display = va_display;
89	  } else if (backend == CudaCopy) {
90	
91	#ifdef ENABLE_CUDA
92	    AVBufferRef *hw_device_ctx = nullptr;
93	    int err = av_hwdevice_ctx_create(&hw_device_ctx, AV_HWDEVICE_TYPE_CUDA,
94	                                     nullptr, nullptr, 0);
95	    if (err < 0)
96	      return NoHarwareDecoding;
97	    m_hwDeviceContext = hw_device_ctx;
98	    m_codecContext->hw_device_ctx = av_buffer_ref(m_hwDeviceContext);
99	    if (!m_codecContext->hw_device_ctx)
100	      return NoHarwareDecoding;
101	    m_codecContext->get_format = get_hw_format;
102	    auto *hwctx =
103	        reinterpret_cast<AVHWDeviceContext *>(m_hwDeviceContext->data);
104	    auto *cuda = reinterpret_cast<AVCUDADeviceContext *>(hwctx->hwctx);
105	    m_cudaContext = cuda->cuda_ctx;
106	#endif
107	  }
108	  // Initialize the HW device
109	  if (av_hwdevice_ctx_init(m_hwDeviceContext) < 0)
110	    return NoHarwareDecoding;
111	
112	  // Attach to decoder
113	  m_codecContext->hw_device_ctx = av_buffer_ref(m_hwDeviceContext);
114	  if (!m_codecContext->hw_device_ctx)
115	    return NoHarwareDecoding;
116	
117	  m_codecContext->get_format = get_hw_format;
118	
119	  if (avcodec_open2(m_codecContext, m_codec, nullptr) < 0)
120	    return NoHarwareDecoding;
121	
122	  m_frame = av_frame_alloc();
123	  if (!m_frame)
124	    return BadVideo;
125	
126	  m_packet = av_packet_alloc();
127	  if (!m_packet)
128	    return BadVideo;
129	
130	  return Success;
131	}
132	// thanks claude
133	bool Wallpaper::decodeNextFrame() {
134	  int ret;
135	
136	  while (true) {
137	    ret = avcodec_receive_frame(m_codecContext, m_frame);
138	    if (ret == 0) {
139	      return true; // got a frame
140	    }
141	    if (ret != AVERROR(EAGAIN)) {
142	      if (ret == AVERROR_EOF) {
143	        // loop: seek back to start and flush decoder state
144	        av_seek_frame(m_formatContext, m_videoStream, 0, AVSEEK_FLAG_BACKWARD);
145	        avcodec_flush_buffers(m_codecContext);
146	        continue; // try receiving again after flush (will hit EAGAIN, fall
147	                  // through to read)
148	      }
149	      return false; // real decode error
150	    }
151	
152	    // EAGAIN: decoder wants more input
153	    av_packet_unref(m_packet);
154	    int readRet = av_read_frame(m_formatContext, m_packet);
155	    if (readRet < 0) {
156	      // EOF on demuxer side, flush decoder to drain remaining frames, then loop
157	      avcodec_send_packet(m_codecContext, nullptr);
158	      continue;
159	    }
160	
161	    if (m_packet->stream_index != m_videoStream) {
162	      av_packet_unref(m_packet);
163	      continue;
164	    }
165	
166	    ret = avcodec_send_packet(m_codecContext, m_packet);
167	    av_packet_unref(m_packet);
168	    if (ret < 0 && ret != AVERROR(EAGAIN)) {
169	      return false;
170	    }
171	    // loop back to receive_frame
172	  }
173	}
174	
175	WallpaperBindError Wallpaper::decodeSingleFrameNV12() {
176	  if (avcodec_open2(m_codecContext, m_codec, nullptr) < 0)
177	    return BadVideo;
178	
179	  m_packet = av_packet_alloc();
180	  if (!m_packet)
181	    return BadVideo;
182	
183	  AVFrame *decoded = av_frame_alloc();
184	  if (!decoded)
185	    return BadVideo;
186	
187	  bool gotFrame = false;
188	  while (av_read_frame(m_formatContext, m_packet) >= 0) {
189	    if (m_packet->stream_index == m_videoStream) {
190	      if (avcodec_send_packet(m_codecContext, m_packet) == 0 &&
191	          avcodec_receive_frame(m_codecContext, decoded) == 0) {
192	        gotFrame = true;
193	        av_packet_unref(m_packet);
194	        break;
195	      }
196	    }
197	    av_packet_unref(m_packet);
198	  }
199	
200	  if (!gotFrame) {
201	    av_frame_free(&decoded);
202	    return BadVideo;
203	  }
204	
205	  if (decoded->format == AV_PIX_FMT_NV12) {
206	    m_frame = decoded; // already NV12, nothing to do
207	  } else {
208	    AVFrame *nv12 = av_frame_alloc();
209	    nv12->format = AV_PIX_FMT_NV12;
210	    nv12->width = decoded->width;
211	    nv12->height = decoded->height;
212	    if (av_frame_get_buffer(nv12, 32) < 0) {
213	      av_frame_free(&decoded);
214	      av_frame_free(&nv12);
215	      return BadVideo;
216	    }
217	
218	    SwsContext *sws =
219	        sws_getContext(decoded->width, decoded->height,
220	                       static_cast<AVPixelFormat>(decoded->format),
221	                       decoded->width, decoded->height, AV_PIX_FMT_NV12,
222	                       SWS_BILINEAR, nullptr, nullptr, nullptr);
223	    if (!sws) {
224	      av_frame_free(&decoded);
225	      av_frame_free(&nv12);
226	      return BadVideo;
227	    }
228	
229	    sws_scale(sws, decoded->data, decoded->linesize, 0, decoded->height,
230	              nv12->data, nv12->linesize);
231	    sws_freeContext(sws);
232	    av_frame_free(&decoded);
233	    m_frame = nv12;
234	  }
235	
236	  return Success;
237	}
