240	  av_packet_free(&m_packet);
241	  av_frame_free(&m_frame);
242	  avcodec_free_context(&m_codecContext);
243	  avformat_close_input(&m_formatContext);
244	  av_buffer_unref(&m_hwDeviceContext);
245	
246	#ifdef ENABLE_CUDA
247	  if (m_cudaContext != nullptr) {
248	    cuCtxDestroy(m_cudaContext);
249	  }
250	#endif
251	}
