  glTexSubImage2D(GL_TEXTURE_2D, 0, 0, 0, width / 2, height / 2, GL_RG,
                  GL_UNSIGNED_BYTE, m_hostUV.data());

  glBindTexture(GL_TEXTURE_2D, 0);
}
