  glBindTexture(GL_TEXTURE_2D, m_renderIntoTempTexture
                                   ? m_toTextures[0]
                                   : m_textures[0]); // Y -> uTexY
  glActiveTexture(GL_TEXTURE1);
  glBindTexture(GL_TEXTURE_2D, m_renderIntoTempTexture
                                   ? m_toTextures[1]
                                   : m_textures[1]); // UV -> uTexC

  if (!m_renderIntoTempTexture) {

    glDrawElements(GL_TRIANGLES, 6, GL_UNSIGNED_INT, 0);

