  if (m_fractScale != 0 && m_daemon.getViewporter() != nullptr) {
    m_bufferWidth = (m_width * m_fractScale + 120 / 2) / 120;
    m_bufferHeight = (m_height * m_fractScale + 120 / 2) / 120;
  } else {
    m_bufferWidth = m_width * m_scale;
    m_bufferHeight = m_height * m_scale;
  }
}

